import requests

def check_endpoint(url, name):
    try:
        response = requests.get(url, timeout=5)
        print(f"{name} ({url}): Status {response.status_code}")
        if response.status_code >= 400:
            print(f"  WARNING: Failed with status {response.status_code}")
        else:
            print(f"  OK: Service healthy")
        return response.status_code
    except Exception as e:
        print(f"{name} ({url}): ERROR - {e}")
        return None

# Check endpoints
check_endpoint('http://localhost:3003/checkConnectivity?variant=2', 'Local Service')
check_endpoint('https://httpstat.us/200', 'HTTPStat')
